require_once __DIR__ . '/includes/auth.php';requireLogin();$pdo=db();$uid=userId();$pageTitle='Tabungan';$activePage='tabungan.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$action=$_POST['action']??'';if($action==='delete'){$st=$pdo->prepare('DELETE FROM savings WHERE id=? AND user_id=?');$st->execute([(int)$_POST['id'],$uid]);flash('success','Tabungan berhasil dihapus.');redirect('tabungan.php');}if($action==='save'){$id=(int)($_POST['id']??0);$name=trim((string)$_POST['name']);$target=parseAmount($_POST['target_amount']??0);$current=parseAmount($_POST['current_amount']??0);$deadline=(string)($_POST['deadline']??'');$desc=trim((string)$_POST['description']);if($name===''||$target<=0||$current<0||!validDate($deadline)){flash('error','Lengkapi nama, nominal, dan deadline tabungan.');redirect('tabungan.php?action='.($id?'edit&id='.$id:'add'));}$current=min($current,$target);if($id){$st=$pdo->prepare('UPDATE savings SET name=?,target_amount=?,current_amount=?,deadline=?,description=? WHERE id=? AND user_id=?');$st->execute([$name,$target,$current,$deadline,$desc,$id,$uid]);}else{$st=$pdo->prepare('INSERT INTO savings(user_id,name,target_amount,current_amount,deadline,description) VALUES(?,?,?,?,?,?)');$st->execute([$uid,$name,$target,$current,$deadline,$desc]);}flash('success','Tabungan berhasil disimpan.');redirect('tabungan.php');}if($action==='move'){$id=(int)$_POST['saving_id'];$amount=parseAmount($_POST['amount']??0);$moveType=$_POST['move_type']==='kurang'?'kurang':'tambah';$date=(string)$_POST['date'];$desc=trim((string)$_POST['description']);$st=$pdo->prepare('SELECT current_amount FROM savings WHERE id=? AND user_id=?');$st->execute([$id,$uid]);$current=(float)$st->fetchColumn();if($amount<=0||!validDate($date)||($moveType==='kurang'&&$amount>$current)){flash('error','Nominal atau tanggal tidak valid. Pengurangan tidak boleh melebihi saldo tabungan.');redirect('tabungan.php?history='.$id);}else{$pdo->beginTransaction();$st=$pdo->prepare('INSERT INTO savings_history(saving_id,amount,type,description,date) VALUES(?,?,?,?,?)');$st->execute([$id,$amount,$moveType,$desc,$date]);$new=$moveType==='tambah'?$current+$amount:$current-$amount;$st=$pdo->prepare('UPDATE savings SET current_amount=? WHERE id=? AND user_id=?');$st->execute([$new,$id,$uid]);$pdo->commit();flash('success',$moveType==='tambah'?'Uang berhasil ditambahkan.':'Uang berhasil dikurangi.');redirect('tabungan.php?history='.$id);}}}
$st=$pdo->prepare('SELECT * FROM savings WHERE user_id=? ORDER BY deadline IS NULL,deadline');$st->execute([$uid]);$rows=$st->fetchAll();$edit=null;if(($_GET['action']??'')==='edit'){$st=$pdo->prepare('SELECT * FROM savings WHERE id=? AND user_id=?');$st->execute([(int)$_GET['id'],$uid]);$edit=$st->fetch()?:null;}if(($_GET['action']??'')==='add')$edit=['id'=>0,'name'=>'','target_amount'=>'','current_amount'=>'','deadline'=>date('Y-m-d',strtotime('+6 months')),'description'=>''];$selected=(int)($_GET['history']??0);$history=[];if($selected){$st=$pdo->prepare('SELECT h.*,s.name FROM savings_history h JOIN savings s ON s.id=h.saving_id WHERE h.saving_id=? AND s.user_id=? ORDER BY h.date DESC,h.id DESC');$st->execute([$selected,$uid]);$history=$st->fetchAll();}$user=currentUser($pdo);require __DIR__.'/includes/header.php';
