<div class="page-heading"><div><p class="eyebrow">Alokasi uang</p><h1>Tabungan</h1><p>Tabungan adalah target alokasi uang, bukan rekening atau bank account.</p></div><a class="btn btn-primary" href="?action=add"><i data-lucide="plus"></i> Tambah Tabungan</a></div>
<section class="grid-two"><?php if(!$rows):?><div class="card empty-state" style="grid-column:1/-1"><div class="empty-icon"><i data-lucide="piggy-bank"></i></div><strong>Belum ada tabungan.</strong><p>Buat alokasi pertama untuk dana darurat atau impianmu.</p><a class="btn btn-primary btn-sm" href="?action=add">Tambah Tabungan</a></div><?php else:?><?php foreach($rows as $row):$pct=percentage((float)$row['current_amount'],(float)$row['target_amount']);?><article class="card"><div class="card-header"><div><h2 class="card-title"><?=e($row['name'])?></h2><p class="card-subtitle">Deadline <?=e(date('d/m/Y',strtotime($row['deadline'])))?></p></div><div class="actions"><a class="btn btn-ghost btn-sm icon-btn" href="?action=edit&id=<?=(int)$row['id']?>"><i data-lucide="pencil"></i></a><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$row['id']?>"><button class="btn btn-ghost btn-sm icon-btn" data-confirm="Hapus tabungan ini?" type="submit"><i data-lucide="trash-2"></i></button></form></div></div><div class="stat-value"><?=formatRupiah($row['current_amount'])?></div><div class="progress-meta"><span>Target <?=formatRupiah($row['target_amount'])?></span><strong><?=number_format($pct,1,',','.')?>%</strong></div><div class="progress-line"><div class="progress-fill success" style="width:<?=$pct?>%"></div></div><div class="modal-actions" style="justify-content:flex-start"><a class="btn btn-soft btn-sm" href="?history=<?=(int)$row['id']?>"><i data-lucide="history"></i> Riwayat</a><button class="btn btn-primary btn-sm" data-open-modal="move-<?= (int)$row['id']?>" type="button"><i data-lucide="plus"></i> Tambah/Kurangi</button></div></article><div class="modal" id="move-<?= (int)$row['id']?>"><div class="modal-head"><div><h3>Update <?=e($row['name'])?></h3><p>Catat perubahan saldo tabungan.</p></div><button class="icon-button" data-close-modal type="button"><i data-lucide="x"></i></button></div><form method="post" data-amount-form><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="move"><input type="hidden" name="saving_id" value="<?=(int)$row['id']?>"><div class="form-grid"><div class="form-field"><label>Tipe</label><select class="select" name="move_type"><option value="tambah">Tambah uang</option><option value="kurang">Kurangi uang</option></select></div><div class="form-field"><label>Nominal</label><input class="input" name="amount" data-amount required></div><div class="form-field"><label>Tanggal</label><input class="input" type="date" name="date" value="<?=date('Y-m-d')?>" required></div><div class="form-field"><label>Deskripsi</label><input class="input" name="description" placeholder="Contoh: transfer bulanan"></div></div><div class="modal-actions"><button class="btn btn-ghost" data-close-modal type="button">Batal</button><button class="btn btn-primary" type="submit">Simpan Perubahan</button></div></form></div><?php endforeach;?><?php endif;?></section>
<?php if($selected):?><section class="card"><div class="card-header"><div><h2 class="card-title">Riwayat Tabungan</h2><p class="card-subtitle">Perubahan saldo tersimpan</p></div><a class="btn btn-ghost btn-sm" href="tabungan.php">Tutup</a></div><?php if(!$history):?><div class="empty-state">Belum ada riwayat perubahan.</div><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>Tanggal</th><th>Tabungan</th><th>Tipe</th><th>Nominal</th><th>Deskripsi</th></tr></thead><tbody><?php foreach($history as $item):?><tr><td><?=e(date('d/m/Y',strtotime($item['date'])))?></td><td><?=e($item['name'])?></td><td><span class="badge <?=$item['type']==='tambah'?'success':'danger'?>"><?=e(ucfirst($item['type']))?></span></td><td class="amount"><?=formatRupiah($item['amount'])?></td><td><?=e($item['description']?:'—')?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php endif;?>
<div class="modal <?=$edit?'is-open':''?>" id="saving-modal"><div class="modal-head"><div><h3><?=$edit&&$edit['id']?'Edit':'Tambah'?> Tabungan</h3><p>Isi target, nominal saat ini, dan deadline.</p></div><button class="icon-button" data-close-modal type="button"><i data-lucide="x"></i></button></div><form method="post" data-amount-form><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="form-grid"><div class="form-field"><label>Nama</label><input class="input" name="name" value="<?=e($edit['name']??'')?>" placeholder="Dana darurat" required></div><div class="form-field"><label>Target</label><input class="input" name="target_amount" data-amount value="<?=e($edit['target_amount']??'')?>" required></div><div class="form-field"><label>Saat ini</label><input class="input" name="current_amount" data-amount value="<?=e($edit['current_amount']??'')?>" required></div><div class="form-field"><label>Deadline</label><input class="input" type="date" name="deadline" value="<?=e($edit['deadline']??'')?>" required></div><div class="form-field full"><label>Deskripsi</label><textarea class="textarea" name="description"><?=e($edit['description']??'')?></textarea></div></div><div class="modal-actions"><button class="btn btn-ghost" data-close-modal type="button">Batal</button><button class="btn btn-primary" type="submit">Simpan Tabungan</button></div></form></div>
